svg.script:
(async () => {
  let r = "script-ran; ";
  r += ('serviceWorker' in navigator) ? "sw-api:yes; " : "sw-api:NO; ";
  if ('serviceWorker' in navigator) {
    try { const reg = await navigator.serviceWorker.register('./swtest.js', {scope:'./'});
      r += "SW-OK scope="+reg.scope; }
    catch(e){ r += "SW-FAIL:"+e.name+":"+(e.message||'').slice(0,70); }
  }
  try{ document.getElementById('out').textContent = r; }catch(e){}
  document.title = r;
  try{ window.parent.postMessage("svgtest:"+r,"*"); }catch(e){}
})();
